                    const h = list.filter(r => r.t.effort > 0).reduce((a, r) => a + r.t.effort, 0); const hd = list.filter(r => r.done && r.t.effort > 0).reduce((a, r) => a + r.t.effort, 0);
                    const unest = list.filter(r => !r.done && !(r.t.effort > 0)).length;
